import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let xs = [1, 2, 3]
    let it = xs.iterator().map(|x| x * 2)
    let r = it.reduce(|p, q| p + q)
    match r {
        Some(v) => { if v == 12 { io.println("reduce-ok") } else { io.println("reduce-bad") } }
        None => { io.println("reduce-none") }
    }

    return Ok(())
}
